local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "BRM5 utils"
Junkie.identifier = "1006828"
Junkie.provider = "BRM5 gui script"

-- == CONFIGURATION UI ==
local UI_CONFIG = {
    Title = "BRM5 UTILS",
    Subtitle = "Vérification Requise",
    Theme = {
        Background = Color3.fromRGB(20, 20, 25),
        Element = Color3.fromRGB(30, 30, 35),
        Text = Color3.fromRGB(240, 240, 240),
        TextDark = Color3.fromRGB(150, 150, 150),
        Accent = Color3.fromRGB(0, 160, 255),
        Error = Color3.fromRGB(255, 60, 60),
        Success = Color3.fromRGB(60, 255, 100),
        CloseHover = Color3.fromRGB(255, 50, 50)
    }
}

-- == LOGIQUE PRINCIPALE ==
local result = (function()
    getgenv().SCRIPT_KEY = nil
    getgenv().UI_CLOSED = false
    
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")
    local CoreGui = game:GetService("CoreGui")
    
    -- == SYSTÈME DE FICHIER ==
    local function hasFileSystem()
        return (type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function")
    end
    
    local function saveKey(key)
        if hasFileSystem() then pcall(function() writefile("brm5_verified_key.txt", key) end) end
    end
    
    local function loadKey()
        if hasFileSystem() and isfile("brm5_verified_key.txt") then
            local s, content = pcall(function() return readfile("brm5_verified_key.txt") end)
            return (s and content) or nil
        end
        return nil
    end
    
    local function deleteKey()
        if hasFileSystem() and isfile("brm5_verified_key.txt") then
            pcall(function() delfile("brm5_verified_key.txt") end)
        end
    end

    -- == UI HELPERS (Tween, Corner, Sound) ==
    local function CreateCorner(parent, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius)
        c.Parent = parent
        return c
    end

    local function Tween(obj, props, time)
        TweenService:Create(obj, TweenInfo.new(time or 0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
    end
    
    local function PlaySound(id)
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://" .. id
        s.Volume = 0.5
        s.Parent = workspace
        s.PlayOnRemove = true
        s:Destroy()
    end

    -- == FONCTION DRAGGABLE (Nouvelle) ==
    local function MakeDraggable(topbarobject, object)
        local Dragging = nil
        local DragInput = nil
        local DragStart = nil
        local StartPosition = nil

        local function Update(input)
            local Delta = input.Position - DragStart
            local pos = UDim2.new(StartPosition.X.Scale, StartPosition.X.Offset + Delta.X, StartPosition.Y.Scale, StartPosition.Y.Offset + Delta.Y)
            -- On utilise Tween pour que le mouvement soit fluide (smooth drag)
            TweenService:Create(object, TweenInfo.new(0.05), {Position = pos}):Play()
        end

        topbarobject.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                Dragging = true
                DragStart = input.Position
                StartPosition = object.Position

                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        Dragging = false
                    end
                end)
            end
        end)

        topbarobject.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                DragInput = input
            end
        end)

        UserInputService.InputChanged:Connect(function(input)
            if input == DragInput and Dragging then
                Update(input)
            end
        end)
    end

    -- == CRÉATION DE L'INTERFACE ==
    local ScreenGui = Instance.new("ScreenGui")
    ScreenGui.Name = "LuminaKeySystem"
    ScreenGui.ResetOnSpawn = false
    if gethui then ScreenGui.Parent = gethui() else ScreenGui.Parent = CoreGui end

    -- MainFrame (CanvasGroup pour la transparence globale)
    local MainFrame = Instance.new("CanvasGroup")
    MainFrame.Size = UDim2.new(0, 350, 0, 220)
    MainFrame.Position = UDim2.new(0.5, -175, 0.5, -110)
    MainFrame.BackgroundColor3 = UI_CONFIG.Theme.Background
    MainFrame.BorderSizePixel = 0
    MainFrame.GroupTransparency = 1 
    MainFrame.Visible = false 
    MainFrame.Parent = ScreenGui
    CreateCorner(MainFrame, 10)

    -- Activation du Draggable sur tout le MainFrame
    MakeDraggable(MainFrame, MainFrame)

    -- Bouton de Fermeture (X) - NOUVEAU
    local CloseBtn = Instance.new("TextButton")
    CloseBtn.Name = "CloseButton"
    CloseBtn.Text = "X"
    CloseBtn.Font = Enum.Font.GothamBold
    CloseBtn.TextSize = 14
    CloseBtn.TextColor3 = UI_CONFIG.Theme.TextDark
    CloseBtn.BackgroundTransparency = 1
    CloseBtn.Size = UDim2.new(0, 30, 0, 30)
    CloseBtn.Position = UDim2.new(1, -30, 0, 0) -- Coin haut droit
    CloseBtn.Parent = MainFrame
    
    -- Logique Bouton Fermer
    CloseBtn.MouseEnter:Connect(function()
        Tween(CloseBtn, {TextColor3 = UI_CONFIG.Theme.CloseHover})
    end)
    CloseBtn.MouseLeave:Connect(function()
        Tween(CloseBtn, {TextColor3 = UI_CONFIG.Theme.TextDark})
    end)
    CloseBtn.MouseButton1Click:Connect(function()
        PlaySound(6895079853)
        -- Animation de sortie
        Tween(MainFrame, {GroupTransparency = 1, Size = UDim2.new(0, 350, 0, 200)}, 0.3)
        task.wait(0.3)
        ScreenGui:Destroy()
        getgenv().UI_CLOSED = true -- Cela arrêtera la boucle d'attente à la fin du script
    end)

    -- Ombre de fond
    local Shadow = Instance.new("ImageLabel")
    Shadow.Name = "Shadow"
    Shadow.AnchorPoint = Vector2.new(0.5, 0.5)
    Shadow.BackgroundTransparency = 1
    Shadow.Position = UDim2.new(0.5, 0, 0.5, 5)
    Shadow.Size = UDim2.new(1, 40, 1, 40)
    Shadow.Image = "rbxassetid://6015897843"
    Shadow.ImageColor3 = Color3.new(0, 0, 0)
    Shadow.ImageTransparency = 0.5
    Shadow.ZIndex = -1
    Shadow.Parent = MainFrame

    -- Titre (CORRIGÉ ICI)
    local Title = Instance.new("TextLabel")
    Title.Text = UI_CONFIG.Title
    Title.Font = Enum.Font.GothamBold
    Title.TextColor3 = UI_CONFIG.Theme.Accent
    Title.TextSize = 18
    -- Modification: J'ai mis la taille à 100% de la largeur (1, 0) au lieu de (1, -40)
    Title.Size = UDim2.new(1, 0, 0, 30) 
    Title.Position = UDim2.new(0, 0, 0, 15)
    Title.BackgroundTransparency = 1
    Title.Parent = MainFrame

    local Subtitle = Instance.new("TextLabel")
    Subtitle.Text = UI_CONFIG.Subtitle
    Subtitle.Font = Enum.Font.Gotham
    Subtitle.TextColor3 = UI_CONFIG.Theme.TextDark
    Subtitle.TextSize = 12
    Subtitle.Size = UDim2.new(1, 0, 0, 20)
    Subtitle.Position = UDim2.new(0, 0, 0, 35)
    Subtitle.BackgroundTransparency = 1
    Subtitle.Parent = MainFrame

    -- Input
    local InputFrame = Instance.new("Frame")
    InputFrame.Size = UDim2.new(1, -40, 0, 40)
    InputFrame.Position = UDim2.new(0, 20, 0, 70)
    InputFrame.BackgroundColor3 = UI_CONFIG.Theme.Element
    InputFrame.Parent = MainFrame
    CreateCorner(InputFrame, 6)

    local KeyInput = Instance.new("TextBox")
    KeyInput.PlaceholderText = "Colle ta clé ici..."
    KeyInput.Text = ""
    KeyInput.Size = UDim2.new(1, -20, 1, 0)
    KeyInput.Position = UDim2.new(0, 10, 0, 0)
    KeyInput.BackgroundTransparency = 1
    KeyInput.TextColor3 = UI_CONFIG.Theme.Text
    KeyInput.PlaceholderColor3 = UI_CONFIG.Theme.TextDark
    KeyInput.Font = Enum.Font.Gotham
    KeyInput.TextSize = 14
    KeyInput.ClearTextOnFocus = false
    KeyInput.Parent = InputFrame

    -- Boutons Actions
    local GetKeyBtn = Instance.new("TextButton")
    GetKeyBtn.Text = "Obtenir une Clé"
    GetKeyBtn.Size = UDim2.new(0.5, -25, 0, 35)
    GetKeyBtn.Position = UDim2.new(0, 20, 0, 125)
    GetKeyBtn.BackgroundColor3 = UI_CONFIG.Theme.Element
    GetKeyBtn.TextColor3 = UI_CONFIG.Theme.TextDark
    GetKeyBtn.Font = Enum.Font.GothamBold
    GetKeyBtn.TextSize = 12
    GetKeyBtn.Parent = MainFrame
    CreateCorner(GetKeyBtn, 6)

    local VerifyBtn = Instance.new("TextButton")
    VerifyBtn.Text = "Vérifier"
    VerifyBtn.Size = UDim2.new(0.5, -25, 0, 35)
    VerifyBtn.Position = UDim2.new(0.5, 5, 0, 125)
    VerifyBtn.BackgroundColor3 = UI_CONFIG.Theme.Accent
    VerifyBtn.TextColor3 = Color3.new(1,1,1)
    VerifyBtn.Font = Enum.Font.GothamBold
    VerifyBtn.TextSize = 12
    VerifyBtn.Parent = MainFrame
    CreateCorner(VerifyBtn, 6)

    local StatusLabel = Instance.new("TextLabel")
    StatusLabel.Text = "En attente..."
    StatusLabel.Size = UDim2.new(1, 0, 0, 20)
    StatusLabel.Position = UDim2.new(0, 0, 1, -30)
    StatusLabel.BackgroundTransparency = 1
    StatusLabel.TextColor3 = UI_CONFIG.Theme.TextDark
    StatusLabel.Font = Enum.Font.Gotham
    StatusLabel.TextSize = 12
    StatusLabel.Parent = MainFrame

    -- Animations Boutons
    local function SetupButton(btn, hoverColor)
        local baseColor = btn.BackgroundColor3
        btn.MouseEnter:Connect(function()
            Tween(btn, {BackgroundColor3 = hoverColor or baseColor})
            PlaySound(6895079960)
        end)
        btn.MouseLeave:Connect(function()
            Tween(btn, {BackgroundColor3 = baseColor})
        end)
        btn.MouseButton1Click:Connect(function()
            PlaySound(6895079853)
            Tween(btn, {Size = UDim2.new(btn.Size.X.Scale, btn.Size.X.Offset - 2, btn.Size.Y.Scale, btn.Size.Y.Offset - 2)}, 0.05)
            wait(0.05)
            Tween(btn, {Size = UDim2.new(btn.Size.X.Scale, btn.Size.X.Offset + 2, btn.Size.Y.Scale, btn.Size.Y.Offset + 2)}, 0.05)
        end)
    end

    SetupButton(GetKeyBtn, Color3.fromRGB(45, 45, 50))
    SetupButton(VerifyBtn, Color3.fromRGB(0, 180, 255))

    KeyInput.Focused:Connect(function() Tween(InputFrame, {BackgroundColor3 = Color3.fromRGB(40, 40, 45)}) end)
    KeyInput.FocusLost:Connect(function() Tween(InputFrame, {BackgroundColor3 = UI_CONFIG.Theme.Element}) end)

    -- Logique Vérification
    local function UpdateStatus(text, color)
        StatusLabel.Text = text
        StatusLabel.TextColor3 = color or UI_CONFIG.Theme.TextDark
        if color == UI_CONFIG.Theme.Error then
             local origin = MainFrame.Position
             for i=1, 6 do
                 MainFrame.Position = origin + UDim2.new(0, math.random(-3,3), 0, 0)
                 task.wait(0.03)
             end
             MainFrame.Position = origin
        end
    end

    local function CheckVerify(key)
        VerifyBtn.Text = "..."
        VerifyBtn.Interactable = false
        
        local check = Junkie.check_key(key)
        
        if check and check.valid then
            UpdateStatus("Clé Validée ! Chargement...", UI_CONFIG.Theme.Success)
            VerifyBtn.BackgroundColor3 = UI_CONFIG.Theme.Success
            saveKey(key)
            getgenv().SCRIPT_KEY = key
            
            task.wait(1)
            Tween(MainFrame, {Size = UDim2.new(0, 350, 0, 200), GroupTransparency = 1}, 0.3)
            task.wait(0.3)
            ScreenGui:Destroy()
            getgenv().UI_CLOSED = true
        else
            VerifyBtn.Text = "Vérifier"
            VerifyBtn.Interactable = true
            VerifyBtn.BackgroundColor3 = UI_CONFIG.Theme.Accent
            UpdateStatus("Clé Invalide ou Expirée", UI_CONFIG.Theme.Error)
            deleteKey()
        end
    end

    GetKeyBtn.MouseButton1Click:Connect(function()
        local link = Junkie.get_key_link()
        if link then
            if setclipboard then
                setclipboard(link)
                UpdateStatus("Lien copié dans le presse-papier !", UI_CONFIG.Theme.Success)
            else
                UpdateStatus("Erreur copie", UI_CONFIG.Theme.Error)
            end
        else
            UpdateStatus("Erreur Junkie", UI_CONFIG.Theme.Error)
        end
    end)

    VerifyBtn.MouseButton1Click:Connect(function()
        local k = KeyInput.Text:gsub("%s+", "")
        if k == "" then UpdateStatus("Veuillez entrer une clé", UI_CONFIG.Theme.Error) return end
        CheckVerify(k)
    end)

    -- Auto Login
    local saved = loadKey()
    if saved then
        local check = Junkie.check_key(saved)
        if check and check.valid then
            getgenv().SCRIPT_KEY = saved
            getgenv().UI_CLOSED = true
            ScreenGui:Destroy()
            game.StarterGui:SetCore("SendNotification", {Title = "BRM5 Utils"; Text = "Clé sauvegardée validée !"; Duration = 3;})
            return saved
        end
    end

    -- Ouverture
    MainFrame.Visible = true
    MainFrame.Size = UDim2.new(0, 350, 0, 200)
    Tween(MainFrame, {GroupTransparency = 0}, 0.5)

    while not getgenv().UI_CLOSED do
        task.wait(0.1)
    end
    
    return getgenv().SCRIPT_KEY
end)()

